const STATEMENT_IMAGE_DECODE_SIZE = 768;
const statementImageRefs = new Map<number, ExpoImageRef>();
const statementImageLoads = new Map<number, Promise<ExpoImageRef | null>>();
const ORGANIZE_EXAMPLE_IMAGE_DECODE_SIZE = 768;
const organizeExampleImageRefs = new Map<number, ExpoImageRef>();
const organizeExampleImageLoads = new Map<number, Promise<ExpoImageRef | null>>();
const HABIT_GOAL_IMAGE_DECODE_SIZE = 960;
const habitGoalImageRefs = new Map<number, ExpoImageRef>();
const habitGoalImageLoads = new Map<number, Promise<ExpoImageRef | null>>();

function loadStatementImage(source: number) {
  const cached = statementImageRefs.get(source);
  if (cached) return Promise.resolve(cached);

  const pending = statementImageLoads.get(source);
  if (pending) return pending;

  const load = ExpoImage.loadAsync(source, {
    maxWidth: STATEMENT_IMAGE_DECODE_SIZE,
    maxHeight: STATEMENT_IMAGE_DECODE_SIZE,
  })
    .then(image => {
      statementImageRefs.set(source, image);
      statementImageLoads.delete(source);
      return image;
    })
    .catch(() => {
      statementImageLoads.delete(source);
      return null;
    });

  statementImageLoads.set(source, load);
  return load;
}

function warmStatementImages(sources: number[]) {
  return Promise.all(sources.map(loadStatementImage));
}

function loadOrganizeExampleImage(source: number) {
  const cached = organizeExampleImageRefs.get(source);
  if (cached) return Promise.resolve(cached);

  const pending = organizeExampleImageLoads.get(source);
  if (pending) return pending;

  const load = ExpoImage.loadAsync(source, {
    maxWidth: ORGANIZE_EXAMPLE_IMAGE_DECODE_SIZE,
    maxHeight: ORGANIZE_EXAMPLE_IMAGE_DECODE_SIZE,
  })
    .then(image => {
      organizeExampleImageRefs.set(source, image);
      organizeExampleImageLoads.delete(source);
      return image;
    })
    .catch(() => {
      organizeExampleImageLoads.delete(source);
      return null;
    });

  organizeExampleImageLoads.set(source, load);
  return load;
}

function warmOrganizeExampleImages(sources: number[]) {
  return Promise.all(sources.map(loadOrganizeExampleImage));
}

function loadHabitGoalImage(source: number) {
  const cached = habitGoalImageRefs.get(source);
  if (cached) return Promise.resolve(cached);

  const pending = habitGoalImageLoads.get(source);
  if (pending) return pending;

  const load = ExpoImage.loadAsync(source, {
    maxWidth: HABIT_GOAL_IMAGE_DECODE_SIZE,
    maxHeight: HABIT_GOAL_IMAGE_DECODE_SIZE,
  })
    .then(image => {
      habitGoalImageRefs.set(source, image);
      habitGoalImageLoads.delete(source);
      return image;
    })
    .catch(() => {
      habitGoalImageLoads.delete(source);
      return null;
    });

  habitGoalImageLoads.set(source, load);
  return load;
}

function warmHabitGoalImages(sources: number[]) {
  return Promise.all(sources.map(loadHabitGoalImage));
}

function releaseStatementImages(sources: number[]) {
  for (const source of sources) {
    const image = statementImageRefs.get(source);
    if (image) {
      try {
        image.release();
      } catch {
        // The native ref may already have been released during a fast remount.
      }
      statementImageRefs.delete(source);
    }

    const pending = statementImageLoads.get(source);
    if (pending) {
      statementImageLoads.delete(source);
      void pending.then(loaded => {
        if (!loaded) return;
        try {
          loaded.release();
        } catch {
          // The native ref may already have been released.
        }
        if (statementImageRefs.get(source) === loaded) {
          statementImageRefs.delete(source);
        }
      });
    }
  }
}

