function stepOrder(answers: Answers): StepId[] {
  const includeMonthlyGoals = shouldIncludeMonthlyGoals(answers);
  const organizeSetup: StepId[] = [
    'organizeSetupPath',
    'organizeMacroIntro',
    'organizeBigEventsIntro',
    'buildBigEvents',
    'organizeMacroProgressAfterBigEvents',
    // On the monthly-goals path the fusion scene plays the whole
    // first-layer-is-set narrative itself — the separate afterAhead layers
    // screen would repeat it, so it only remains on the shorter path.
    ...(includeMonthlyGoals
      ? ['organizeMonthlyGoalsIntro' as StepId, 'buildMonthlyGoals' as StepId, 'organizeMacroProgressAfterMonthlyGoals' as StepId]
      : ['organizeSetupPathAfterAhead' as StepId]),
    'organizeWeeklyIntroV2',
    'organizeWeeklyRhythmV2',
    'organizeDailySetupV2',
    'organizeHubStartV2',
    'organizeSpiritualTasksIntro',
    'organizeSpiritualBuilderV2',
    'organizeHubAfterSpiritualV2',
    'organizeRoutineTasksIntro',
    'organizeRoutineBuilderV2',
    'organizeHubAfterRoutineV2',
    'organizeChallengesIntro',
    'organizeChallengesBuilderV2',
    'organizeHubAfterChallengesV2',
    'organizeHabitsConceptV2',
    'organizeHabitsExamples',
    'organizeHabitsMomentumV2',
    'organizeHabitsBuilderV2',
    'organizeHubCompleteV2',
    'organizeGuidedHomeTour',
  ];

  return [
    'welcome',
    ...(ONBOARDING_DEV_JUMP_ENABLED ? ['onboardingDevJump' as StepId] : []),
    'nameIntro',
    'traditionIntro',
    'valueOrganize',
    'valueDiscipline',
    'valueFocus',
    'valueFaith',
    'toolsShowcase',
    'protectDeck',
    'screenTimeSlider',
    'dayVisualizationHeader',
    'protectRecap',
    'flameProtect',
    'organizeDeck',
    'organizeRecap',
    ...organizeSetup,
    'flameOrganize',
    'giftMoment',
    'bibleWalkthrough',
    'prayerBook',
    'flameGrow',
    'toolsSlides',
    'flameTools',
    'homeReveal',
    'firstCheckoff',
    'privacy',
    'callingClose',
    'paywall',
    'postPaywallBrand',
    'age',
    'gender',
    'accountCreation',
  ];
}

function selectedFor(step: StepId, answers: Answers) {
  if (step === 'christian') return answers.christian;
  if (step === 'tradition') return answers.tradition;
  if (step === 'age') return answers.age;
  if (step === 'gender') return answers.gender;
  if (step === 'commitment') return answers.commitment;
  if (step === 'pillars') return answers.primaryPillar;
  if (step === 'routine') return answers.routine;
  if (step === 'focus') return answers.focus;
  return undefined;
}

function selectedValuesFor(step: StepId, answers: Answers): string[] {
  if (step === 'valueReflect') return answers.valueReflection ?? [];
  if (step === 'reason') return answers.reasons ?? [];
  const selected = selectedFor(step, answers);
  return selected ? [selected] : [];
}

function getOptions(step: StepId): Option<string>[] {
  if (step === 'valueReflect') return VALUE_REFLECT_OPTIONS;
  if (step === 'commitment') return COMMITMENT_OPTIONS;
  if (step === 'christian') return CHRISTIAN_OPTIONS;
  if (step === 'tradition') return TRADITION_OPTIONS;
  if (step === 'age') return AGE_OPTIONS;
  if (step === 'gender') return GENDER_OPTIONS;
  if (step === 'reason') return REASON_OPTIONS;
  return [];
}

function isSecularTradition(tradition?: TraditionAnswer) {
  return tradition === 'not_christian' || tradition === 'prefer_not';
}

