// Deo 3 — setup loop. The settled clean list becomes a checklist: tap a tool to
// "set it up" (a brief busy state, like leaving to configure it and returning),
// then it lands a gold check + haptic. When all are done the board auto-advances
// to the flame screen. This is an onboarding-only simulated setup — it does NOT
// drive the real tools.
function V4RecapToolsBoard({ groups, selected, onNext }: { groups: RecapProblemGroup[]; selected: string[]; onNext: () => void }) {
  const recs = useMemo(
    () =>
      groups
        .filter(group => group.cardIds.some(id => selected.includes(id)))
        .slice(0, 3),
    [groups, selected],
  );
  const [reveal, setReveal] = useState(0);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [completedCount, setCompletedCount] = useState(0);
  const finishingRef = useRef(false);
  const selectedKey = selected.join('|');

  useEffect(() => {
    finishingRef.current = false;
    preloadTaskFeedbackSound();
    setReveal(0);
    setActiveIndex(-1);
    setCompletedCount(0);
  }, [selectedKey]);

  useEffect(() => {
    if (reveal < recs.length) {
      const t = setTimeout(() => {
        setReveal(c => c + 1);
      }, reveal === 0 ? 420 : 680);
      return () => clearTimeout(t);
    }

    if (recs.length > 0 && activeIndex < 0) {
      const finalCardEntranceDelay = 220 + Math.max(0, recs.length - 1) * 320;
      const finalCardSettleDelay = finalCardEntranceDelay + 620 + 360;
      const t = setTimeout(() => {
        setActiveIndex(0);
        runSelectionHaptic();
      }, finalCardSettleDelay);
      return () => clearTimeout(t);
    }

    return undefined;
  }, [activeIndex, recs.length, reveal]);

  const handleContinue = useCallback(() => {
    if (finishingRef.current) return;
    if (recs.length === 0) {
      finishingRef.current = true;
      onNext();
      return;
    }
    if (activeIndex < 0) return;

    void playTaskCompleteFeedback();
    setCompletedCount(current => Math.max(current, activeIndex + 1));

    if (activeIndex >= recs.length - 1) {
      finishingRef.current = true;
      setTimeout(onNext, 720);
      return;
    }

    setTimeout(() => {
      setActiveIndex(activeIndex + 1);
    }, 620);
  }, [activeIndex, onNext, recs.length]);

  const ctaVisible = reveal >= recs.length && (recs.length === 0 || activeIndex >= 0);

  return (
    <View style={s.v4RecapSlide}>
      <ScrollView
        contentContainerStyle={s.v4RecapToolsScrollContent}
        showsVerticalScrollIndicator={false}
      >
        <Reanimated.View entering={FadeIn.duration(440)} style={s.v4RecapToolsHeader}>
          <Text style={s.v4RecapToolsTitle}>
            Your setup path
          </Text>
          <Text style={s.v4RecapToolsSubtitle}>
            {recs.length > 0
              ? 'Based on your answers, we’ll set up the parts that can help you most.'
              : 'This section does not need extra setup right now.'}
          </Text>
        </Reanimated.View>

        <View style={s.v4RecapToolsBoard}>
          {recs.slice(0, reveal).map((group, i) => {
            const done = i < completedCount;
            const active = i === activeIndex && !done;
            return (
              <React.Fragment key={group.id}>
                <V4RecapToolCard group={group} index={i} active={active} done={done} />
                {i < Math.min(reveal, recs.length) - 1 ? (
                  <V4RecapPathConnector accent={recs[i + 1]?.accent ?? group.accent} index={i} />
                ) : null}
              </React.Fragment>
            );
          })}
        </View>
      </ScrollView>

      <AnimatedCta active={ctaVisible} delay={220} style={s.questionFooter} pointerEvents={ctaVisible ? 'auto' : 'none'}>
        <View style={s.ctaIsland}>
          <TouchableOpacity activeOpacity={0.9} haptic="none" onPress={handleContinue} style={s.primaryButton}>
            <Text style={s.primaryButtonText}>
              {recs.length > 0 && activeIndex >= recs.length - 1 ? 'Finish setup' : 'Continue'}
            </Text>
            <ChevronRight s={19} c="#FFFFFF" w={2.5} />
          </TouchableOpacity>
        </View>
      </AnimatedCta>
    </View>
  );
}

// Phase A (answers reveal + days card + purge) → Phase B (gold loading) →
// Phase C (tools — recommended tools with accordion reason drawers, Deo 2).
type OrganizeSetupMapVariant = 'start' | 'afterAhead';
type OrganizeSetupAreaId = 'macro' | 'weekly';
type OrganizeSetupAfterAheadStage = 0 | 1 | 2;

const ORGANIZE_RULE_AREAS: {
  id: OrganizeSetupAreaId;
  layerLabel: string;
  title: string;
  subtitle: string;
  accent: string;
  icon: React.ReactNode;
  parts: string[];
}[] = [
  {
    id: 'macro',
    layerLabel: 'First layer',
    title: 'Macro planning',
    subtitle: 'First the month gets a shape. Big dates and monthly goals are set before the week begins, so nothing important catches you unprepared.',
    accent: '#4D8586',
    icon: <Calendar s={22} c="#4D8586" w={2} />,
    parts: ['Big events', 'Monthly goals'],
  },
  {
    id: 'weekly',
    layerLabel: 'Second layer',
    title: 'Weekly routine',
    subtitle: 'Then the week itself. Prayer, duties, challenges and habits each receive a fixed place, so ordinary days carry what matters to you.',
    accent: GOLD,
    icon: <ListChecks s={22} c={GOLD} w={2} />,
    parts: ['Spiritual tasks', 'Routine tasks', 'Challenges', 'Habits'],
  },
];

// Shared header for every organize stage screen — the carousel-grade title
// (big serif, accent underline, serif body) so the title sits in the same
// place on every screen of the sequence. These screens never show a back
// button: the onboarding moves forward only, like every section before it.
function OrganizeStageHeader({
  title,
  body,
  accent = GOLD,
  compact = false,
  variant = 'default',
  bodyHighlights = [],
  titleLines = 2,
  titleStyle,
  staged = false,
}: {
  title: string;
  body: string;
  accent?: string;
  compact?: boolean;
  variant?: 'default' | 'premium';
  bodyHighlights?: string[];
  titleLines?: number;
  titleStyle?: StyleProp<TextStyle>;
  // Staged: the header speaks in order — title rises, the underline draws
  // from its centre, the body follows. Default keeps the single-block fade
  // used across the other organize screens.
  staged?: boolean;
}) {
  const premium = variant === 'premium';
  const titleNode = (
    <Text
      style={[
        s.organizeStageTitle,
        premium && s.organizeStageTitlePremium,
        compact && (premium ? s.organizeStageTitlePremiumCompact : s.organizeStageTitleCompact),
        titleStyle,
      ]}
      numberOfLines={titleLines}
      adjustsFontSizeToFit
      minimumFontScale={premium ? 0.78 : 0.68}
    >
      {title}
    </Text>
  );
  const underlineStyle = [s.organizeStageUnderline, premium && s.organizeStageUnderlinePremium, { backgroundColor: accent }] as StyleProp<ViewStyle>;
  const bodyNode = renderHighlightedBodyText(body, bodyHighlights, premium ? s.organizePremiumBodyStrong : s.organizeBigEventsBodyStrong);
  const bodyTextStyle = [s.organizeBigEventsBody, premium && s.organizePremiumBody] as StyleProp<TextStyle>;

  if (staged) {
    return (
      <View style={[s.organizeBigEventsHeader, premium && s.organizePremiumHeader]}>
        <View style={s.organizeBigEventsTitleWrap}>
          <Reanimated.View
            entering={FadeInUp.duration(540).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
              opacity: 0,
              transform: [{ translateY: 16 }],
            })}
          >
            {titleNode}
          </Reanimated.View>
          <Reanimated.View
            entering={FadeIn.delay(200).duration(460).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
              opacity: 0,
              transform: [{ scaleX: 0.22 }],
            })}
            style={underlineStyle}
          />
        </View>
        <Reanimated.Text
          entering={FadeInUp.delay(280).duration(540).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
            opacity: 0,
            transform: [{ translateY: 12 }],
          })}
          style={bodyTextStyle}
        >
          {bodyNode}
        </Reanimated.Text>
      </View>
    );
  }

  return (
    <Reanimated.View
      entering={FadeInUp.duration(560).easing(Easing.out(Easing.cubic))}
      style={[s.organizeBigEventsHeader, premium && s.organizePremiumHeader]}
    >
      <View style={s.organizeBigEventsTitleWrap}>
        {titleNode}
        <View style={underlineStyle} />
      </View>
      <Text style={bodyTextStyle}>{bodyNode}</Text>
    </Reanimated.View>
  );
}

function renderHighlightedBodyText(text: string, highlights: string[], highlightStyle: StyleProp<TextStyle>) {
  if (!highlights.length) return text;

  const parts: React.ReactNode[] = [];
  let cursor = 0;

  while (cursor < text.length) {
    let nextIndex = -1;
    let nextHighlight = '';

    for (const highlight of highlights) {
      const index = text.indexOf(highlight, cursor);
      if (index !== -1 && (nextIndex === -1 || index < nextIndex)) {
        nextIndex = index;
        nextHighlight = highlight;
      }
    }

    if (nextIndex === -1) {
      parts.push(text.slice(cursor));
      break;
    }

    if (nextIndex > cursor) parts.push(text.slice(cursor, nextIndex));
    parts.push(
      <Text key={`${nextHighlight}-${nextIndex}`} style={highlightStyle}>
        {nextHighlight}
      </Text>,
    );
    cursor = nextIndex + nextHighlight.length;
  }

  return parts;
}

function organizeMapState(variant: OrganizeSetupMapVariant, id: OrganizeSetupAreaId, afterAheadStage: OrganizeSetupAfterAheadStage = 2) {
  const done = id === 'macro' && variant === 'afterAhead' && afterAheadStage >= 1;
  const active =
    (variant === 'start' && id === 'macro') ||
    (variant === 'afterAhead' && id === 'weekly' && afterAheadStage >= 2);
  return { active, done };
}

function SetupPathStepCard({
  title,
  body,
  accent,
  icon,
  index,
  active,
  done,
  activeReady = true,
  enteringDelay,
  entering,
}: {
  title: string;
  body: string;
  accent: string;
  icon: React.ReactNode;
  index: number;
  active: boolean;
  done: boolean;
  activeReady?: boolean;
  enteringDelay?: number;
  entering?: React.ComponentProps<typeof Reanimated.View>['entering'];
}) {
  const isActive = active && activeReady;
  const state = useSharedValue(done ? 2 : isActive ? 1 : 0);
  const isGold = accent === GOLD;

  useEffect(() => {
    state.value = withSpring(done ? 2 : isActive ? 1 : 0, {
      damping: 16,
      stiffness: 178,
      mass: 0.84,
    });
  }, [done, isActive, state]);

  const cardStyle = useAnimatedStyle(() => ({
    opacity: interpolate(state.value, [0, 1, 2], [0.72, 1, 0.98]),
    transform: [
      { scale: interpolate(state.value, [0, 1, 2], [0.985, 1.018, 1]) },
      { translateY: interpolate(state.value, [0, 1, 2], [0, -2, 0]) },
    ],
  }));
  const displayAccent = done ? (isGold ? GOLD : '#2F9B61') : accent;
  const gradientColors = done
    ? isGold
      ? (['rgba(255,252,243,1)', 'rgba(197,160,89,0.30)', 'rgba(255,245,219,0.96)'] as const)
      : (['rgba(250,255,251,1)', 'rgba(47,155,97,0.24)', 'rgba(245,252,246,0.96)'] as const)
    : isActive
      ? (['rgba(255,255,255,1)', `${accent}14`, 'rgba(255,255,255,0.95)'] as const)
      : (['rgba(255,255,255,0.96)', 'rgba(247,243,236,0.48)', 'rgba(255,255,255,0.82)'] as const);

  return (
    <Reanimated.View
      entering={entering ?? FadeInUp.delay(enteringDelay ?? 0).duration(600).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
        opacity: 0,
        transform: [{ translateY: 24 }, { scale: 0.965 }],
      })}
      style={[
        s.v4ToolCard,
        s.v4ToolPathCard,
        s.setupPathUnifiedCard,
        !isActive && !done && s.v4SetupQueueCardInactive,
        isActive && s.v4SetupCardActive,
        done && [
          s.setupPathCardDone,
          {
            borderColor: `${displayAccent}40`,
            shadowColor: displayAccent,
          },
        ],
        cardStyle,
      ]}
    >
      <LinearGradient
        pointerEvents="none"
        colors={gradientColors}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      <View style={[s.v4ToolTopSheen, { backgroundColor: `${displayAccent}${isActive || done ? '22' : '10'}` }]} />
      <View style={s.v4ToolHeader}>
        <View
          style={[
            s.v4RecapGroupIcon,
            s.v4ToolIcon,
            !isActive && !done && s.v4SetupQueueIconInactive,
            { backgroundColor: `${displayAccent}14`, borderColor: `${displayAccent}36` },
          ]}
        >
          <View
            style={[
              s.v4ToolStepMini,
              {
                borderColor: done ? `${displayAccent}46` : isActive ? `${displayAccent}48` : 'rgba(25,23,20,0.11)',
                backgroundColor: done ? (isGold ? '#FFF6D9' : '#F2FBF4') : isActive ? '#FFFDF8' : '#F4EFE5',
              },
            ]}
          >
            <Text style={[s.v4ToolStepBadgeText, { color: done ? displayAccent : isActive ? accent : 'rgba(25,23,20,0.34)' }]}>
              {index + 1}
            </Text>
          </View>
          {icon}
        </View>
        <View style={[s.v4RecapGroupCopy, s.setupPathCardCopy]}>
          <Text style={[s.v4RecapGroupTitle, !isActive && !done && s.v4SetupQueueTitleInactive]}>{title}</Text>
          <Text style={[s.v4RecapGroupSubtitle, !isActive && !done && s.v4SetupQueueSubtitleInactive]}>{body}</Text>
        </View>
        <V4SetupStatusMark active={isActive && !done} done={done} accent={displayAccent} />
      </View>
    </Reanimated.View>
  );
}

