function OrganizeSpiritualTaskBuilderSlide({ onNext }: { onNext: () => void }) {
  const insets = useSafeAreaInsets();
  const { height } = useWindowDimensions();
  const { createOrUpdateTask } = useTasks();
  const [sheetTask, setSheetTask] = useState<SpiritualTaskSuggestion | null>(null);
  const [editorTask, setEditorTask] = useState<SpiritualTaskSuggestion | null>(null);
  const [savedTasks, setSavedTasks] = useState<SavedSpiritualEntry[]>([]);
  const [freshKey, setFreshKey] = useState<string | null>(null);
  const savedIds = useMemo(() => new Set(savedTasks.map(task => task.suggestionId)), [savedTasks]);
  const compact = height < 750;
  const suggestionsHeight = compact
    ? Math.max(178, Math.min(236, height * 0.27))
    : Math.max(224, Math.min(326, height * 0.32));
  const ready = savedTasks.length > 0;
  const footerStyle = [s.questionFooter, { bottom: insets.bottom + 14 }];
  const contentStyle = [
    s.spiritualBuilderContent,
    {
      paddingTop: Math.max(insets.top + 40, compact ? 52 : 58),
      paddingBottom: insets.bottom + 98,
      rowGap: compact ? 9 : 13,
    },
  ];

  const selectTask = (item: SpiritualTaskSuggestion) => {
    runSelectionHaptic();
    if (item.setup.kind === 'editor') setEditorTask(item);
    else setSheetTask(item);
  };

  // A real task was just created — celebrate it into the "My" panel.
  const completeSave = useCallback((item: SpiritualTaskSuggestion, draft: TaskDraft) => {
    const key = `${item.id}-${Date.now()}`;
    setSavedTasks(prev => {
      if (prev.some(task => task.suggestionId === item.id)) return prev;
      return [...prev, { key, suggestionId: item.id, card: spiritualDraftToTaskData(draft) }];
    });
    setFreshKey(key);
    runPreviewTaskCheckHaptic();
    void playTaskCheckSoundOnly();
    setTimeout(() => {
      setFreshKey(current => (current === key ? null : current));
    }, 1050);
  }, []);

  return (
    <View style={s.organizeRuleScreen}>
      <View style={contentStyle}>
        <Reanimated.View
          entering={FadeInUp.duration(520).easing(Easing.out(Easing.cubic))}
          style={s.spiritualBuilderHeader}
        >
          <Text style={s.spiritualBuilderTitle}>Build your spiritual rhythm.</Text>
          <View style={s.spiritualBuilderTitleUnderline} />
          <Text style={s.spiritualBuilderSubtitle}>
            Choose the prayer and Scripture tasks you want Anasta to place into your week.
          </Text>
        </Reanimated.View>

        <Reanimated.View
          entering={FadeInUp.delay(120).duration(520).easing(Easing.out(Easing.cubic))}
          style={[s.spiritualBuilderMyPanel, compact && s.spiritualBuilderMyPanelCompact]}
        >
          <View style={s.spiritualBuilderPanelHeader}>
            <Text style={s.spiritualBuilderPanelTitle}>My Spiritual Tasks</Text>
            <Text style={s.spiritualBuilderPanelCount}>{savedTasks.length}</Text>
          </View>
          {savedTasks.length ? (
            <ScrollView
              nestedScrollEnabled
              showsVerticalScrollIndicator={false}
              contentContainerStyle={s.spiritualBuilderSavedList}
            >
              {savedTasks.map(task => (
                <Reanimated.View
                  key={task.key}
                  entering={FadeInUp.duration(480).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
                    opacity: 0,
                    transform: [{ translateY: 18 }, { scale: 0.965 }],
                  })}
                  layout={LinearTransition.duration(260).easing(Easing.out(Easing.cubic))}
                >
                  <SpiritualSavedTaskCard card={task.card} fresh={freshKey === task.key} />
                </Reanimated.View>
              ))}
            </ScrollView>
          ) : (
            <View style={s.spiritualBuilderEmptyState}>
              <View style={s.spiritualBuilderEmptyIcon}>
                <Candle s={18} c={GOLD} w={2} />
              </View>
              <Text style={s.spiritualBuilderEmptyTitle}>No spiritual tasks yet</Text>
              <Text style={s.spiritualBuilderEmptyBody}>Choose one below, set a rhythm, and it will appear here.</Text>
            </View>
          )}
        </Reanimated.View>

        <Reanimated.View
          entering={FadeInUp.delay(210).duration(520).easing(Easing.out(Easing.cubic))}
          style={[s.spiritualBuilderSuggestionWindow, { maxHeight: suggestionsHeight }]}
        >
          <View style={s.spiritualBuilderSuggestionHeader}>
            <Text style={s.spiritualBuilderSuggestionTitle}>Spiritual Tasks</Text>
            <Text style={s.spiritualBuilderSuggestionHint}>Tap to set up</Text>
          </View>
          <ScrollView
            nestedScrollEnabled
            showsVerticalScrollIndicator={false}
            contentContainerStyle={s.spiritualBuilderSuggestionList}
          >
            {SPIRITUAL_TASK_SUGGESTION_GROUPS.map(group => {
              const groupItems = group.items.filter(item => !savedIds.has(item.id));
              if (!groupItems.length) return null;
              return (
                <Reanimated.View
                  key={group.id}
                  style={s.spiritualBuilderGroup}
                  layout={LinearTransition.duration(260).easing(Easing.out(Easing.cubic))}
                >
                  <Text style={s.spiritualBuilderGroupTitle}>{group.title}</Text>
                  {groupItems.map(item => (
                    <Reanimated.View
                      key={item.id}
                      exiting={FadeOut.duration(200)}
                      layout={LinearTransition.duration(260).easing(Easing.out(Easing.cubic))}
                    >
                      <TouchableOpacity
                        activeOpacity={0.9}
                        haptic="none"
                        onPress={() => selectTask(item)}
                        style={s.spiritualBuilderSuggestionPress}
                      >
                        <SpiritualTaskPreviewCard item={item} muted />
                      </TouchableOpacity>
                    </Reanimated.View>
                  ))}
                </Reanimated.View>
              );
            })}
            {!savedIds.has(SPIRITUAL_CUSTOM_TASK.id) ? (
              <TouchableOpacity
                activeOpacity={0.9}
                haptic="none"
                onPress={() => selectTask(SPIRITUAL_CUSTOM_TASK)}
                style={s.spiritualBuilderCustomButton}
              >
                <View style={s.spiritualBuilderCustomIcon}>
                  <Plus s={18} c="#2F9B61" w={2.4} />
                </View>
                <Text style={s.spiritualBuilderCustomText}>Add custom spiritual task</Text>
              </TouchableOpacity>
            ) : null}
          </ScrollView>
        </Reanimated.View>
      </View>

      {sheetTask ? (
        <SetAsTaskSheet
          visible={!!sheetTask}
          context={sheetTask.setup.kind === 'sheet' ? sheetTask.setup.context : 'prayer'}
          initialPrayerType={sheetTask.setup.kind === 'sheet' ? sheetTask.setup.prayerType : undefined}
          initialScriptureType={sheetTask.setup.kind === 'sheet' ? sheetTask.setup.scriptureType : undefined}
          onClose={() => setSheetTask(null)}
          onTaskDraft={async draft => {
            const target = sheetTask;
            await createOrUpdateTask(draft);
            if (target) completeSave(target, draft);
          }}
        />
      ) : null}

      <RoutineTaskEditorSheet
        visible={!!editorTask}
        task={null}
        defaultLevel={1}
        defaultType={editorTask?.setup.kind === 'editor' ? editorTask.setup.type : 'custom'}
        onClose={() => setEditorTask(null)}
        onSave={async task => {
          const target = editorTask;
          const draft = routineTaskToDraft(task);
          await createOrUpdateTask(draft);
          setEditorTask(null);
          if (target) completeSave(target, draft);
        }}
        onDelete={() => {}}
      />

      {ready ? (
        <AnimatedCta active delay={120} style={footerStyle} pointerEvents="auto">
          <View style={s.ctaIsland}>
            <TouchableOpacity activeOpacity={0.9} haptic="medium" onPress={onNext} style={s.primaryButton}>
              <Text style={s.primaryButtonText}>Continue</Text>
              <ChevronRight s={19} c="#FFFFFF" w={2.5} />
            </TouchableOpacity>
          </View>
        </AnimatedCta>
      ) : null}
    </View>
  );
}

// Habits explained through one lived example: a goal holds several steps,
// and even an imperfect day still moves you forward. The card acts the
// story out — two steps check themselves, one is missed, and the progress
// bar still climbs.
const HABIT_STORY_STEPS = [
  { id: 'walk', title: 'Morning walk', time: '07:30' },
  { id: 'gym', title: 'Gym session', time: '17:00' },
  { id: 'run', title: 'Evening run', time: '20:00' },
];

function OrganizeHabitStorySlide({ onNext }: { onNext: () => void }) {
  const [phase, setPhase] = useState(0);
  const progress = useSharedValue(0);

  // phase 1: walk checks · 2: gym checks · 3: run misses · 4: the lesson lands
  useEffect(() => {
    const timers = [
      setTimeout(() => {
        setPhase(1);
        runPreviewTaskCheckHaptic();
        void playTaskCheckSoundOnly();
        progress.value = withTiming(1 / 3, { duration: 520, easing: Easing.out(Easing.cubic) });
      }, 900),
      setTimeout(() => {
        setPhase(2);
        runPreviewTaskCheckHaptic();
        void playTaskCheckSoundOnly();
        progress.value = withTiming(2 / 3, { duration: 520, easing: Easing.out(Easing.cubic) });
      }, 1750),
      setTimeout(() => {
        setPhase(3);
        runSelectionHaptic();
      }, 2600),
      setTimeout(() => {
        setPhase(4);
        runBubbleHaptic();
      }, 3250),
    ];
    return () => timers.forEach(clearTimeout);
  }, [progress]);

  const progressStyle = useAnimatedStyle(() => ({
    width: `${progress.value * 100}%`,
  }));

  return (
    <OrganizeLessonSlide
      title="A habit is a goal with steps."
      body="You name the goal, then choose the small actions that build it. Miss one step and you are still moving — the goal holds you, not the single day."
      accent="#2F9B61"
      ctaLabel="See examples"
      onNext={onNext}
    >
      <Reanimated.View
        entering={FadeInUp.delay(200).duration(560).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
          opacity: 0,
          transform: [{ translateY: 24 }, { scale: 0.97 }],
        })}
        style={s.habitStoryCard}
      >
        <LinearGradient
          pointerEvents="none"
          colors={['rgba(255,255,255,1)', 'rgba(47,155,97,0.12)', 'rgba(255,255,255,0.94)']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
        />
        <View style={s.habitStoryHeader}>
          <View style={s.habitStoryGoalIcon}>
            <Target s={19} c="#2F9B61" w={2.1} />
          </View>
          <View style={s.habitStoryGoalCopy}>
            <Text style={s.habitStoryGoalLabel}>THE GOAL</Text>
            <Text style={s.habitStoryGoalTitle}>Get in shape</Text>
          </View>
        </View>

        <View style={s.habitStoryProgressTrack}>
          <Reanimated.View style={[s.habitStoryProgressFill, progressStyle]} />
        </View>

        <View style={s.habitStorySteps}>
          {HABIT_STORY_STEPS.map((step, index) => {
            const checked = phase >= index + 1 && index < 2;
            const missed = phase >= 3 && index === 2;
            return (
              <View key={step.id} style={s.habitStoryStepRow}>
                <View
                  style={[
                    s.habitStoryStepCheck,
                    checked && s.habitStoryStepCheckDone,
                    missed && s.habitStoryStepCheckMissed,
                  ]}
                >
                  {checked ? (
                    <Reanimated.View
                      entering={FadeIn.duration(220).withInitialValues({ opacity: 0, transform: [{ scale: 0.4 }] })}
                    >
                      <CheckSmall s={13} c="#FFFFFF" w={3} />
                    </Reanimated.View>
                  ) : null}
                  {missed ? <View style={s.habitStoryStepMissDash} /> : null}
                </View>
                <Text style={[s.habitStoryStepTitle, missed && s.habitStoryStepTitleMissed]}>
                  {step.title}
                </Text>
                <Text style={s.habitStoryStepTime}>{step.time}</Text>
              </View>
            );
          })}
        </View>

        {phase >= 4 ? (
          <Reanimated.View
            entering={FadeInUp.duration(430).easing(Easing.out(Easing.cubic))}
            style={s.habitStoryLesson}
          >
            <LottieFlame size={22} />
            <Text style={s.habitStoryLessonText}>
              2 of 3 today — still moving toward the goal.
            </Text>
          </Reanimated.View>
        ) : null}
      </Reanimated.View>
    </OrganizeLessonSlide>
  );
}

type SavedRoutineEntry = {
  key: string;
  exampleId: string | null;
  card: TaskData;
};

// The routine mirror of the spiritual builder: your tasks gather on top,
// a real editor adds new ones, and examples below prefill that same editor.
function OrganizeRoutineTaskBuilderSlide({ onNext }: { onNext: () => void }) {
  const insets = useSafeAreaInsets();
  const { height } = useWindowDimensions();
  const { createOrUpdateTask } = useTasks();
  const [editorPrefill, setEditorPrefill] = useState<RoutineTask | null>(null);
  const [editorExampleId, setEditorExampleId] = useState<string | null>(null);
  const [editorOpen, setEditorOpen] = useState(false);
  const [savedTasks, setSavedTasks] = useState<SavedRoutineEntry[]>([]);
  const [freshKey, setFreshKey] = useState<string | null>(null);
  const savedExampleIds = useMemo(
    () => new Set(savedTasks.map(task => task.exampleId).filter(Boolean) as string[]),
    [savedTasks]
  );
  const compact = height < 750;
  const suggestionsHeight = compact
    ? Math.max(168, Math.min(226, height * 0.26))
    : Math.max(214, Math.min(312, height * 0.31));
  const ready = savedTasks.length > 0;
  const footerStyle = [s.questionFooter, { bottom: insets.bottom + 14 }];
  const contentStyle = [
    s.spiritualBuilderContent,
    {
      paddingTop: Math.max(insets.top + 40, compact ? 52 : 58),
      paddingBottom: insets.bottom + 98,
      rowGap: compact ? 9 : 13,
    },
  ];

  const openBlankEditor = () => {
    runSelectionHaptic();
    setEditorExampleId(null);
    setEditorPrefill(null);
    setEditorOpen(true);
  };

  const openExampleEditor = (example: RoutineTaskExample) => {
    runSelectionHaptic();
    setEditorExampleId(example.id);
    setEditorPrefill(routineExampleToPrefill(example));
    setEditorOpen(true);
  };

  const completeSave = useCallback((exampleId: string | null, draft: TaskDraft) => {
    const key = `${exampleId ?? 'custom'}-${Date.now()}`;
    setSavedTasks(prev => [...prev, { key, exampleId, card: routineDraftToTaskData(draft) }]);
    setFreshKey(key);
    runPreviewTaskCheckHaptic();
    void playTaskCheckSoundOnly();
    setTimeout(() => {
      setFreshKey(current => (current === key ? null : current));
    }, 1050);
  }, []);

  return (
    <View style={s.organizeRuleScreen}>
      <View style={contentStyle}>
        <Reanimated.View
          entering={FadeInUp.duration(520).easing(Easing.out(Easing.cubic))}
          style={s.spiritualBuilderHeader}
        >
          <Text style={s.spiritualBuilderTitle}>Give ordinary duties a place.</Text>
          <View style={[s.spiritualBuilderTitleUnderline, s.routineBuilderTitleUnderline]} />
          <Text style={s.spiritualBuilderSubtitle}>
            Add the responsibilities you repeat, so the week has structure before it begins.
          </Text>
        </Reanimated.View>

        <Reanimated.View
          entering={FadeInUp.delay(120).duration(520).easing(Easing.out(Easing.cubic))}
          style={[s.spiritualBuilderMyPanel, s.routineBuilderMyPanel, compact && s.spiritualBuilderMyPanelCompact]}
        >
          <View style={s.spiritualBuilderPanelHeader}>
            <Text style={[s.spiritualBuilderPanelTitle, s.routineBuilderPanelTitle]}>My Routine Tasks</Text>
            <Text style={[s.spiritualBuilderPanelCount, s.routineBuilderPanelCount]}>{savedTasks.length}</Text>
          </View>
          {savedTasks.length ? (
            <ScrollView
              nestedScrollEnabled
              showsVerticalScrollIndicator={false}
              contentContainerStyle={s.spiritualBuilderSavedList}
            >
              {savedTasks.map(task => (
                <Reanimated.View
                  key={task.key}
                  entering={FadeInUp.duration(480).easing(Easing.bezier(0.16, 1, 0.28, 1)).withInitialValues({
                    opacity: 0,
                    transform: [{ translateY: 18 }, { scale: 0.965 }],
                  })}
                  layout={LinearTransition.duration(260).easing(Easing.out(Easing.cubic))}
                >
                  <SpiritualSavedTaskCard card={task.card} fresh={freshKey === task.key} />
                </Reanimated.View>
              ))}
            </ScrollView>
          ) : (
            <View style={s.spiritualBuilderEmptyState}>
              <View style={[s.spiritualBuilderEmptyIcon, s.routineBuilderEmptyIcon]}>
                <ListChecks s={18} c="#4D8586" w={2} />
              </View>
              <Text style={s.spiritualBuilderEmptyTitle}>No routine tasks yet</Text>
              <Text style={s.spiritualBuilderEmptyBody}>Add your own below, or start from an example.</Text>
            </View>
          )}
        </Reanimated.View>

        <Reanimated.View entering={FadeInUp.delay(180).duration(520).easing(Easing.out(Easing.cubic))}>
          <TouchableOpacity
            activeOpacity={0.9}
            haptic="medium"
            onPress={openBlankEditor}
            style={s.routineBuilderAddButton}
          >
            <View style={s.routineBuilderAddIcon}>
              <Plus s={16} c="#FFFFFF" w={2.6} />
            </View>
            <Text style={s.routineBuilderAddText}>Add routine task</Text>
          </TouchableOpacity>
        </Reanimated.View>

        <Reanimated.View
          entering={FadeInUp.delay(240).duration(520).easing(Easing.out(Easing.cubic))}
          style={[s.spiritualBuilderSuggestionWindow, { maxHeight: suggestionsHeight }]}
        >
          <View style={s.spiritualBuilderSuggestionHeader}>
            <Text style={[s.spiritualBuilderSuggestionTitle, s.routineBuilderPanelTitle]}>Examples</Text>
            <Text style={s.spiritualBuilderSuggestionHint}>Tap to set up</Text>
          </View>
          <ScrollView
            nestedScrollEnabled
            showsVerticalScrollIndicator={false}
            contentContainerStyle={s.spiritualBuilderSuggestionList}
          >
            {ROUTINE_TASK_EXAMPLE_ITEMS.filter(example => !savedExampleIds.has(example.id)).map(example => (
              <Reanimated.View
                key={example.id}
                exiting={FadeOut.duration(200)}
                layout={LinearTransition.duration(260).easing(Easing.out(Easing.cubic))}
              >
                <TouchableOpacity
                  activeOpacity={0.9}
                  haptic="none"
                  onPress={() => openExampleEditor(example)}
                  style={s.spiritualBuilderSuggestionPress}
                >
                  <View style={[s.spiritualBuilderTaskFrame, s.spiritualBuilderTaskFrameMuted]}>
                    <AnyTaskCard task={routineExampleToTaskData(example)} />
                    <View pointerEvents="none" style={s.spiritualBuilderTaskMutedOverlay} />
                  </View>
                </TouchableOpacity>
              </Reanimated.View>
            ))}
          </ScrollView>
        </Reanimated.View>
      </View>

      <RoutineTaskEditorSheet
        visible={editorOpen}
        task={editorPrefill}
        defaultLevel={2}
        defaultType="custom"
        onClose={() => {
          setEditorOpen(false);
          setEditorPrefill(null);
          setEditorExampleId(null);
        }}
        onSave={async task => {
          const exampleId = editorExampleId;
          const draft = routineTaskToDraft(task);
          await createOrUpdateTask(draft);
          setEditorOpen(false);
          setEditorPrefill(null);
          setEditorExampleId(null);
          completeSave(exampleId, draft);
        }}
        onDelete={() => {}}
      />

      {ready ? (
        <AnimatedCta active delay={120} style={footerStyle} pointerEvents="auto">
          <View style={s.ctaIsland}>
            <TouchableOpacity activeOpacity={0.9} haptic="medium" onPress={onNext} style={s.primaryButton}>
              <Text style={s.primaryButtonText}>Continue</Text>
              <ChevronRight s={19} c="#FFFFFF" w={2.5} />
            </TouchableOpacity>
          </View>
        </AnimatedCta>
      ) : null}
    </View>
  );
}

// ============================================================================
// ORGANIZE — WEEKLY ROUTINE, V2
// The weekly section rebuilt as final screens: no back buttons, titles on the
// carousel line, Home-real task cards, and every save creating a real task.
// ============================================================================

// The most consistent hour a draft was given: the base time, or — when days
// carry their own times — the hour chosen most often (earliest wins a tie).
function draftConsistentTime(draft: TaskDraft): string {
  const schedule = draft.schedule;
  if (!schedule) return '23:59';
  const overrides = Object.values(schedule.dayTimes ?? {});
  if (schedule.sameTimeEveryDay || overrides.length === 0) return schedule.time;
  const counts = new Map<string, number>();
  [schedule.time, ...overrides].forEach(time => counts.set(time, (counts.get(time) ?? 0) + 1));
  let best = schedule.time;
  let bestCount = 0;
  [...counts.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .forEach(([time, count]) => {
      if (count > bestCount) {
        best = time;
        bestCount = count;
      }
    });
  return best;
}

