const SYSTEM_BUILD_STEPS = [
  'Weekly rhythm in place',
  'Big events in view',
  'Habits tied to goals',
  'Preparing your Home',
];
// Irregular on purpose — real work never ticks like a metronome.
const SYSTEM_BUILD_TICKS = [620, 1560, 2120, 3040];
const SYSTEM_BUILD_DONE_AT = 4100;
// Home mounts beneath the veil only AFTER the last row has ticked: its heavy
// first render blocks the JS thread, and any pending tick timers would all
// fire at once the moment it finished.
const SYSTEM_BUILD_HOME_MOUNT_AT = 3140;

// The pulsing "being worked on" marker of the current loading row.
function SysVeilWorkingDot() {
  const cycle = useSharedValue(0);

  useEffect(() => {
    cycle.value = 0;
    cycle.value = withRepeat(withTiming(1, { duration: 1300, easing: Easing.linear }), -1, false);
    return () => cancelAnimation(cycle);
  }, [cycle]);

  const ringStyle = useAnimatedStyle(() => {
    const p = interpolate(cycle.value, [0.06, 0.85], [0, 1], 'clamp');
    return {
      opacity: interpolate(p, [0, 0.15, 1], [0, 0.6, 0], 'clamp'),
      transform: [{ scale: 0.45 + p * 1.05 }],
    };
  });
  const dotStyle = useAnimatedStyle(() => ({
    transform: [{ scale: interpolate(cycle.value, [0, 0.1, 0.24, 1], [1, 0.78, 1, 1], 'clamp') }],
  }));

  return (
    <View style={s.sysVeilWorkBox}>
      <Reanimated.View style={[s.sysVeilWorkRing, ringStyle]} />
      <Reanimated.View style={[s.sysVeilWorkDot, dotStyle]} />
    </View>
  );
}

// Plays over the real Home while it does its heavy first render: by the time
// "Creating your system" finishes ticking, the screen underneath is warm and
// the reveal lands without a stutter. Styled after the onboarding intro
// loading screens: logo plate, gold rule, big serif line, warm floor glow.
function SystemBuildVeil({ onDone }: { onDone: () => void }) {
  const [ticked, setTicked] = useState(0);
  const onDoneRef = useRef(onDone);
  onDoneRef.current = onDone;

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];
    SYSTEM_BUILD_TICKS.forEach((at, index) => {
      timers.push(setTimeout(() => {
        if (index === SYSTEM_BUILD_TICKS.length - 1) {
          Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
        } else {
          runSelectionHaptic();
        }
        setTicked(index + 1);
      }, at));
    });
    timers.push(setTimeout(() => {
      onDoneRef.current();
    }, SYSTEM_BUILD_DONE_AT));
    return () => timers.forEach(clearTimeout);
  }, []);

  return (
    <Reanimated.View exiting={FadeOut.duration(460)} style={s.sysVeil}>
      <View pointerEvents="none" style={s.introWarmth}>
        <LinearGradient
          colors={['rgba(255,255,255,0)', 'rgba(246,225,202,0.46)', 'rgba(255,241,225,0.98)']}
          locations={[0, 0.52, 1]}
          style={StyleSheet.absoluteFill}
        />
      </View>
      <View style={s.sysVeilContent}>
        <Reanimated.View
          entering={FadeInLeft.duration(420).withInitialValues({
            opacity: 0,
            transform: [{ translateX: -16 }],
          })}
          style={s.introLogoFrame}
        >
          <View style={s.introLogoPlate}>
            <Image source={APP_LOGO} style={s.introLogo} resizeMode="cover" />
          </View>
        </Reanimated.View>
        <Reanimated.View entering={FadeIn.delay(90).duration(320)} style={s.introRule} />
        <Reanimated.View
          entering={FadeInRight.delay(140).duration(460).withInitialValues({
            opacity: 0,
            transform: [{ translateX: 16 }],
          })}
          style={s.introCopy}
        >
          <Text style={s.sysVeilEyebrow}>ONE MOMENT</Text>
          <Text style={s.introTitle}>Creating{'\n'}your system.</Text>
        </Reanimated.View>
        <View style={s.sysVeilRows}>
          {SYSTEM_BUILD_STEPS.map((step, index) => {
            const done = index < ticked;
            const current = index === ticked;
            return (
              <Reanimated.View
                key={step}
                entering={FadeInUp.delay(360 + index * 90).duration(400).easing(Easing.out(Easing.cubic))}
                style={s.sysVeilRow}
              >
                <View
                  style={[
                    s.sysVeilRowIcon,
                    done && s.sysVeilRowIconDone,
                    !done && !current && s.sysVeilRowIconIdle,
                  ]}
                >
                  {done ? (
                    <Reanimated.View entering={ZoomIn.springify().damping(12).stiffness(260).mass(0.6)}>
                      <CheckSmall s={12} c="#FFFFFF" w={3} />
                    </Reanimated.View>
                  ) : current ? (
                    <SysVeilWorkingDot />
                  ) : null}
                </View>
                <Text
                  style={[
                    s.sysVeilRowText,
                    done && s.sysVeilRowTextDone,
                    current && s.sysVeilRowTextCurrent,
                  ]}
                >
                  {step}
                </Text>
              </Reanimated.View>
            );
          })}
        </View>
        <Reanimated.View entering={FadeIn.delay(680).duration(420)} style={s.sysVeilBar}>
          <Reanimated.View
            layout={LinearTransition.duration(430).easing(Easing.out(Easing.cubic))}
            style={[s.sysVeilBarFill, { width: `${(ticked / SYSTEM_BUILD_STEPS.length) * 100}%` }]}
          />
        </Reanimated.View>
      </View>
    </Reanimated.View>
  );
}

function OrganizeRealHomeGuideSlide({ onNext }: { onNext: () => void }) {
  const { beginGuidedSetup, endGuidedSetup, patchSession, setPresentation } = useGuidedSetup();
  const [stage, setStage] = useState<'loading' | 'home' | 'routine'>('loading');
  // Home's heavy first render is deferred a beat, so the cut from the habits
  // builder lands on a calm, already-opaque loading scene — not on a stutter.
  const [homeWarm, setHomeWarm] = useState(false);
  const sessionStartedRef = useRef(false);

  useEffect(() => {
    // Kill any stale restored session before the fresh tour begins.
    endGuidedSetup();
    const timer = setTimeout(() => setHomeWarm(true), SYSTEM_BUILD_HOME_MOUNT_AT);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (stage !== 'home' || sessionStartedRef.current) return;
    sessionStartedRef.current = true;
    beginGuidedSetup({
      currentChapter: 'build',
      chapterOrder: ['build'],
      activeStep: 'homeClimax',
      phase: 'intro',
      route: '/onboarding',
    });
  }, [beginGuidedSetup, stage]);

  // The session ends only when the slide truly leaves the stage.
  useEffect(() => () => endGuidedSetup(), [endGuidedSetup]);

  const handleHomeComplete = useCallback(() => {
    // One continuous session: hand the baton to the routine tour by patching
    // the step — an end→begin gap here is exactly where the overlay used to
    // fall through and strand the user on a half-dimmed screen.
    setPresentation(null);
    patchSession({ activeStep: 'buildMyRoutine', phase: 'tourWeek', route: '/onboarding' });
    setStage('routine');
  }, [patchSession, setPresentation]);

  const handleRoutineComplete = useCallback(() => {
    endGuidedSetup();
    onNext();
  }, [endGuidedSetup, onNext]);

  return (
    <Reanimated.View entering={FadeIn.duration(240)} style={s.screen}>
      <Reanimated.View
        key={stage === 'routine' ? 'stage-routine' : 'stage-home'}
        entering={FadeIn.duration(260)}
        style={{ flex: 1, backgroundColor: '#FAF7F0' }}
      >
        {stage === 'routine' ? (
          <MyRoutineView guided onGuidedComplete={handleRoutineComplete} />
        ) : homeWarm ? (
          <HomeView guided={stage === 'home'} onGuidedComplete={handleHomeComplete} />
        ) : (
          <View style={{ flex: 1, backgroundColor: '#FAF7F0' }} />
        )}
      </Reanimated.View>
      {/* Root host carries the tour over BOTH screens — MyRoutineView itself
          only mounts hosts inside its bottom sheets (for in-modal phases). */}
      <GuidedOverlayHost />
      {stage === 'loading' && <SystemBuildVeil onDone={() => setStage('home')} />}
    </Reanimated.View>
  );
}

// ─── Bible walkthrough ────────────────────────────────────────────────────────
// Four real scripture screens carried by one continuous guided session:
// the reader on the slogan chapter (Ephesians 5, pre-seeded with our comment
// and a highlight), My Favorites with the color shelves, a deep-link back
// into John 16, and the Bible Notes shelf.
const BIBLE_GUIDE_SLOGAN = { bookId: 49, chapter: 5, verse: 14 };
const BIBLE_GUIDE_SEED_VERSE = 16;
const BIBLE_GUIDE_RETURN = { bookId: 43, chapter: 16, verse: 33 };

function BibleGuideSlide({ onNext }: { onNext: () => void }) {
  const { beginGuidedSetup, endGuidedSetup, patchSession, setPresentation } = useGuidedSetup();
  const { ready, categories, getChapter, upsertAnnotations, updateCategory } = useScripture();
  const { settings } = useAppSettings();
  const [scene, setScene] = useState<'reader1' | 'favorites' | 'reader2' | 'notes'>('reader1');
  // The reader mounts only after seeding is done: every seed write refreshes
  // the whole scripture context, and mounting the reader inside that render
  // storm is exactly where the tour used to go down.
  const [seeded, setSeeded] = useState(false);
  const seedStartedRef = useRef(false);
  const sessionStartedRef = useRef(false);

  // Seed the page the tour opens on: our comment on the slogan verse, a gold
  // highlight two verses below, and the Encouragement verse waiting in
  // Favorites. Real annotations — they stay with the user after onboarding.
  useEffect(() => {
    if (!ready || seedStartedRef.current) return;
    seedStartedRef.current = true;
    // A stale session restored from storage (a killed earlier run) must not
    // drive the screens while we are still seeding.
    endGuidedSetup();
    let alive = true;
    (async () => {
      try {
        const lang = normalizeScriptureLanguage(settings.bibleLang);
        const [ephesians, john] = await Promise.all([
          getChapter(BIBLE_GUIDE_SLOGAN.bookId, BIBLE_GUIDE_SLOGAN.chapter, lang),
          getChapter(BIBLE_GUIDE_RETURN.bookId, BIBLE_GUIDE_RETURN.chapter, lang),
        ]);
        const sloganVerse = ephesians.find(verse => verse.verse === BIBLE_GUIDE_SLOGAN.verse);
        const seedVerse = ephesians.find(verse => verse.verse === BIBLE_GUIDE_SEED_VERSE);
        const courageVerse = john.find(verse => verse.verse === BIBLE_GUIDE_RETURN.verse);
        const inputs = [];
        if (sloganVerse) {
          inputs.push({
            kind: 'comment' as const,
            color: 'gold' as const,
            bookId: BIBLE_GUIDE_SLOGAN.bookId,
            chapter: BIBLE_GUIDE_SLOGAN.chapter,
            verse: BIBLE_GUIDE_SLOGAN.verse,
            text: sloganVerse.text,
            comment: 'Anasta begins here — the call to wake, and to walk as a child of light.',
          });
        }
        if (seedVerse) {
          inputs.push({
            kind: 'highlight' as const,
            color: 'gold' as const,
            bookId: BIBLE_GUIDE_SLOGAN.bookId,
            chapter: BIBLE_GUIDE_SLOGAN.chapter,
            verse: BIBLE_GUIDE_SEED_VERSE,
            text: seedVerse.text,
          });
        }
        if (courageVerse) {
          inputs.push({
            kind: 'highlight' as const,
            color: 'orange' as const,
            bookId: BIBLE_GUIDE_RETURN.bookId,
            chapter: BIBLE_GUIDE_RETURN.chapter,
            verse: BIBLE_GUIDE_RETURN.verse,
            text: courageVerse.text,
          });
        }
        if (inputs.length > 0) await upsertAnnotations(inputs);
        // Rename the seventh color only while it still wears its default name.
        const orange = categories.find(category => category.color === 'orange');
        if (!orange || orange.label === 'Zeal') await updateCategory('orange', 'Encouragement');
      } catch (error) {
        console.warn('[BibleGuide] seeding failed', error);
      }
      if (!alive || sessionStartedRef.current) return;
      sessionStartedRef.current = true;
      beginGuidedSetup({
        currentChapter: 'grow',
        chapterOrder: ['grow'],
        activeStep: 'riseBibleHighlight',
        phase: 'readerIntro',
        route: '/onboarding',
      });
      setSeeded(true);
    })();
    return () => {
      alive = false;
    };
  }, [beginGuidedSetup, categories, endGuidedSetup, getChapter, ready, settings.bibleLang, updateCategory, upsertAnnotations]);

  useEffect(() => () => endGuidedSetup(), [endGuidedSetup]);

  const handleReaderAdvance = useCallback((event: 'sceneDone' | 'openNotes') => {
    setPresentation(null);
    if (event === 'sceneDone') {
      patchSession({ phase: 'favIntro' });
      setScene('favorites');
      return;
    }
    patchSession({ phase: 'noteEntry' });
    setScene('notes');
  }, [patchSession, setPresentation]);

  const handleFavoritesAdvance = useCallback(() => {
    setPresentation(null);
    patchSession({ phase: 'returnIntro' });
    setScene('reader2');
  }, [patchSession, setPresentation]);

  const handleNotesComplete = useCallback(() => {
    endGuidedSetup();
    onNext();
  }, [endGuidedSetup, onNext]);

  return (
    <View style={s.screen}>
      <View style={{ flex: 1, backgroundColor: '#FCFCFC' }}>
        {!seeded ? (
          <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
            <ActivityIndicator color={GOLD} />
          </View>
        ) : (
          <>
            {scene === 'reader1' && (
              <ScriptureReaderView
                guided
                bookId={BIBLE_GUIDE_SLOGAN.bookId}
                chapter={BIBLE_GUIDE_SLOGAN.chapter}
                initialVerse={BIBLE_GUIDE_SLOGAN.verse}
                onBack={() => {}}
                canGoPrevChapter={false}
                canGoNextChapter={false}
                onGuidedAdvance={handleReaderAdvance}
              />
            )}
            {scene === 'favorites' && (
              <MyFavoritesView guided onGuidedAdvance={handleFavoritesAdvance} />
            )}
            {scene === 'reader2' && (
              <ScriptureReaderView
                guided
                bookId={BIBLE_GUIDE_RETURN.bookId}
                chapter={BIBLE_GUIDE_RETURN.chapter}
                initialVerse={BIBLE_GUIDE_RETURN.verse}
                onBack={() => {}}
                canGoPrevChapter={false}
                canGoNextChapter={false}
                onGuidedAdvance={handleReaderAdvance}
              />
            )}
            {scene === 'notes' && (
              <BibleNotesView
                guided
                initialBookId={BIBLE_GUIDE_RETURN.bookId}
                initialChapter={BIBLE_GUIDE_RETURN.chapter}
                onGuidedComplete={handleNotesComplete}
              />
            )}
          </>
        )}
      </View>
      <GuidedOverlayHost />
    </View>
  );
}

