    activeStep === 'organizeWeeklyRhythmV2' ||
    activeStep === 'organizeDailySetupV2' ||
    activeStep === 'organizeHubStartV2' ||
    activeStep === 'organizeSpiritualBuilderV2' ||
    activeStep === 'organizeHubAfterSpiritualV2' ||
    activeStep === 'organizeRoutineBuilderV2' ||
    activeStep === 'organizeHubAfterRoutineV2' ||
    activeStep === 'organizeChallengesBuilderV2' ||
    activeStep === 'organizeHubAfterChallengesV2' ||
    activeStep === 'organizeHabitsConceptV2' ||
    activeStep === 'organizeHabitsMomentumV2' ||
    activeStep === 'organizeHabitsBuilderV2' ||
    activeStep === 'organizeHubCompleteV2' ||
    activeStep === 'organizeGuidedHomeTour' ||
    activeStep === 'dayVisualizationHeader' ||
    valueStepActive ||
    flameStepActive ||
    activeStep === 'bridge' ||
    activeStep === 'organizeIntro' ||
    activeStep === 'taskSetup';
  const stageBottomPadding = activeStep === 'questionIntro' || edgeToEdgeMessage ? 0 : insets.bottom + 8;
  const stageTopPadding = edgeToEdgeMessage ? 0 : hideTopChrome ? insets.top + 12 : 0;
  const stageHorizontalPadding = edgeToEdgeMessage ? 0 : 20;

